/* ===== GLASS CARD ===== */
.glass-card {
  background: var(--glass);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  border-radius: 14px;
  transition: border-color 0.3s, box-shadow 0.3s;
}

/* ===== BADGE ===== */
.badge {
  display: inline-flex; align-items: center; gap: 0.4rem;
  padding: 0.28rem 0.8rem; border-radius: 999px;
  font-size: 0.76rem; font-weight: 600; letter-spacing: 0.04em;
}
.badge-blue  { background: rgba(41,121,255,0.13); color: var(--blue);  border: 1px solid rgba(41,121,255,0.28); }
.badge-cyan  { background: rgba(0,229,255,0.11);  color: var(--cyan);  border: 1px solid rgba(0,229,255,0.25); }
.badge-gold  { background: rgba(255,214,0,0.11);  color: var(--gold);  border: 1px solid rgba(255,214,0,0.25); }
.badge-teal  { background: rgba(0,191,165,0.11);  color: var(--teal);  border: 1px solid rgba(0,191,165,0.25); }
.badge-gray  { background: rgba(136,153,187,0.11);color: var(--text-muted); border: 1px solid rgba(136,153,187,0.2); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex; align-items: center; gap: 0.55rem;
  padding: 0.85rem 2rem; border-radius: 999px;
  font-weight: 600; font-size: 1rem; cursor: pointer;
  border: none; transition: all 0.3s; font-family: 'Inter', sans-serif;
}
.btn-primary {
  background: var(--blue); color: #fff;
  box-shadow: 0 0 28px rgba(41,121,255,0.45);
}
.btn-primary:hover {
  filter: brightness(1.12);
  box-shadow: 0 0 40px rgba(41,121,255,0.65);
  transform: translateY(-2px);
}
.btn-outline {
  background: transparent; color: var(--cyan);
  border: 1.5px solid var(--cyan);
}
.btn-outline:hover {
  background: rgba(0,229,255,0.08);
  box-shadow: 0 0 24px rgba(0,229,255,0.35);
  transform: translateY(-2px);
}
.btn-sm { padding: 0.55rem 1.35rem; font-size: 0.9rem; }

/* ===== FADE-IN ===== */
.fade-in { opacity: 0; transform: translateY(28px); transition: opacity 0.7s ease, transform 0.7s ease; }
.fade-in.visible { opacity: 1; transform: translateY(0); }
.fade-in.d1 { transition-delay: 0.1s; }
.fade-in.d2 { transition-delay: 0.2s; }
.fade-in.d3 { transition-delay: 0.3s; }
.fade-in.d4 { transition-delay: 0.4s; }

/* ===== WAVES ===== */
.wave-wrap { display: block; line-height: 0; overflow: hidden; }
.wave-wrap svg { display: block; }

/* ============================================================
   NAVBAR
============================================================ */
#navbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  padding: 1.2rem 0;
  transition: background 0.4s, padding 0.4s, backdrop-filter 0.4s, border-color 0.4s;
  border-bottom: 1px solid transparent;
}
#navbar.scrolled {
  background: var(--bg-nav);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-bottom-color: var(--border);
  padding: 0.7rem 0;
}
.nav-inner { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }

.nav-logo {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.45rem; font-weight: 700; letter-spacing: 0.04em;
  color: var(--cyan); text-shadow: 0 0 20px rgba(0,229,255,0.4);
  white-space: nowrap;
}
.nav-logo span { color: var(--text); }

.nav-links {
  display: none; align-items: center; gap: 0.15rem; list-style: none;
}
.nav-links a {
  padding: 0.5rem 0.9rem; border-radius: 8px;
  font-size: 0.95rem; font-weight: 500; color: var(--text-muted);
  transition: color 0.25s, background 0.25s;
}
.nav-links a:hover { color: var(--text); background: rgba(255,255,255,0.06); }

.nav-right { display: none; align-items: center; gap: 0.75rem; }

