  font-family: 'JetBrains Mono', monospace; font-size: 0.78rem;
  text-transform: uppercase; letter-spacing: 0.12em;
  color: var(--text-muted); margin-bottom: 1.2rem;
}
.wc-cloud {
  position: relative; width: 100%; padding-bottom: 95%;
  min-height: 320px;
}
.wc-cloud-inner {
  position: absolute; inset: 0; overflow: hidden;
}
.wc-cloud-inner::before {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(ellipse 70% 55% at 50% 50%, rgba(41,121,255,0.06) 0%, transparent 70%),
    radial-gradient(ellipse 45% 40% at 25% 35%, rgba(0,229,255,0.05) 0%, transparent 65%),
    radial-gradient(ellipse 40% 35% at 75% 65%, rgba(0,191,165,0.05) 0%, transparent 65%);
}
.wc-w {
  position: absolute; font-family: 'Space Grotesk', sans-serif;
  font-weight: 700; line-height: 1; white-space: nowrap; cursor: default;
  transition: filter 0.25s, opacity 0.25s;
  opacity: 0.82;
  animation: wc-pulse var(--pd, 5s) ease-in-out var(--pp, 0s) infinite;
}
.wc-w:hover { opacity: 1; filter: brightness(1.4) drop-shadow(0 0 8px currentColor); z-index: 10; }
@keyframes wc-pulse {
  0%, 100% { opacity: 0.82; }
  50%       { opacity: 1; }
}
.wc-w.r90  { transform: rotate(90deg);  transform-origin: top left; }
.wc-w.rn90 { transform: rotate(-90deg); transform-origin: bottom left; }

