/* ── Keynote featured card ── */
.keynote-card {
  max-width: 900px; margin: 0 auto;
  border-radius: 22px; overflow: hidden;
}

.keynote-banner {
  background: linear-gradient(135deg, #1a56db 0%, var(--cyan) 55%, var(--teal) 100%);
  padding: 1.1rem 2rem;
  display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap;
  position: relative; overflow: hidden;
}
.keynote-banner::after {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.12) 50%, transparent 100%);
  background-size: 200% 100%;
  animation: kn-shimmer 3s linear infinite;
}
@keyframes kn-shimmer {
  0%   { background-position: -200% 0; }
  100% { background-position:  200% 0; }
}
.keynote-banner .badge {
  background: rgba(255,255,255,0.18);
  border-color: rgba(255,255,255,0.35);
  color: #fff; position: relative; z-index: 1;
}

.keynote-body {
  padding: 2.25rem 2rem;
  display: flex; flex-direction: column; align-items: center; gap: 2rem;
}
@media (min-width: 640px) {
  .keynote-body { flex-direction: row; align-items: flex-start; }
}

/* Glowing photo ring */
.keynote-photo-wrap { position: relative; flex-shrink: 0; }
.keynote-photo-wrap::before {
  content: '';
  position: absolute; inset: -5px;
  border-radius: 50%;
  background: conic-gradient(var(--blue), var(--cyan), var(--teal), var(--blue));
  animation: kn-ring 4s linear infinite;
  z-index: 0;
}
@keyframes kn-ring {
  to { transform: rotate(360deg); }
}
.keynote-photo {
  position: relative; z-index: 1;
  width: 190px; height: 190px; border-radius: 50%;
  object-fit: cover; object-position: center 20%;
  border: 4px solid var(--bg-card);
  display: block;
}
.keynote-flag {
  position: absolute; bottom: 8px; right: 8px;
  font-size: 1.3rem; line-height: 1; z-index: 2;
}

.keynote-content { display: flex; flex-direction: column; gap: 0.7rem; flex: 1; }

.keynote-title {
  border-left: 3px solid var(--cyan);
  padding-left: 1rem;
  font-style: italic;
  font-size: 1.05rem;
  line-height: 1.65;
  color: var(--text);
  margin: 0.25rem 0;
}

.keynote-stats {
  display: flex; flex-wrap: wrap; gap: 0.55rem; margin-top: 0.25rem;
}
.kn-stat {
  display: inline-flex; align-items: center; gap: 0.4rem;
  padding: 0.3rem 0.85rem; border-radius: 999px;
  font-size: 0.78rem; font-weight: 600;
  background: rgba(41,121,255,0.1); color: var(--blue);
  border: 1px solid rgba(41,121,255,0.25);
}

.keynote-pillars {
  display: flex; flex-wrap: wrap; gap: 0.5rem; margin-top: 0.1rem;
}
.kn-pillar {
  padding: 0.32rem 0.9rem; border-radius: 10px; font-size: 0.82rem; font-weight: 600;
  background: var(--glass); border: 1px solid var(--border); color: var(--text-muted);
}

