/* ── Portrait person card (organizers + keynote photo col) ── */
.person-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.25rem;
}
@media (min-width: 640px)  { .person-grid { grid-template-columns: repeat(3, 1fr); } }
@media (min-width: 1024px) { .person-grid { grid-template-columns: repeat(5, 1fr); } }

.person-card {
  border-radius: 14px; overflow: hidden;
  background: #060b15;
  transition: transform 0.3s, box-shadow 0.3s;
  display: flex; flex-direction: column;
}
.person-card:hover { transform: translateY(-6px); box-shadow: 0 16px 48px rgba(0,0,0,0.6); }

.person-photo-area { position: relative; }
.person-photo {
  width: 100%; aspect-ratio: 3/4;
  object-fit: cover; object-position: top center;
  display: block;
}
.person-overlay {
  position: absolute; bottom: 0; left: 0; right: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.92) 0%, rgba(0,0,0,0.55) 55%, transparent 100%);
  padding: 2.5rem 0.9rem 0.75rem;
}
