}
.person-overlay-name {
  font-size: 1rem; font-weight: 700; color: #fff;
  text-decoration: underline;
  text-decoration-color: rgba(255,255,255,0.45);
  text-underline-offset: 3px; line-height: 1.25;
}

.person-footer {
  padding: 0.65rem 0.9rem;
  display: flex; align-items: center; gap: 0.5rem;
  background: #060b15;
}
.person-link-btn, .person-detail-btn {
  width: 32px; height: 32px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 0.85rem; text-decoration: none;
  border: 1px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.75);
  transition: background 0.2s, color 0.2s, transform 0.2s;
  cursor: pointer; flex-shrink: 0;
}
.person-link-btn:hover, .person-detail-btn:hover {
  background: rgba(255,255,255,0.2); color: #fff; transform: scale(1.1);
}
.person-affil {
  font-size: 0.72rem; color: rgba(255,255,255,0.45); line-height: 1.4; flex: 1;
}

