function initCountdown(target) {
  function pad(n) { return String(n).padStart(2, '0'); }
  // All deadline card mini-countdowns: [targetMs, [d-id, h-id, m-id]]
  const miniCards = [
    [target,                                      ['mcd-d',  'mcd-h',  'mcd-m' ]],  // May 13 submission
    [new Date('2026-06-11T11:59:00Z').getTime(),  ['mcd2-d', 'mcd2-h', 'mcd2-m']],  // Jun 10 notification
    [new Date('2026-07-02T11:59:00Z').getTime(),  ['mcd3-d', 'mcd3-h', 'mcd3-m']],  // Jul 1  camera-ready
    [new Date('2026-07-17T11:59:00Z').getTime(),  ['mcd4-d', 'mcd4-h', 'mcd4-m']],  // Jul 16 author reg
  ];
  function tick() {
    const now = Date.now();
    // Hero countdown (submission deadline only)
    const diff = target - now;
    const d = diff > 0 ? Math.floor(diff / 86400000) : 0;
    const h = diff > 0 ? Math.floor((diff % 86400000) / 3600000) : 0;
    const m = diff > 0 ? Math.floor((diff % 3600000) / 60000) : 0;
    const s = diff > 0 ? Math.floor((diff % 60000) / 1000) : 0;
    [['cd-days',d],['cd-hours',h],['cd-mins',m],['cd-secs',s]].forEach(([id,v]) => {
      const el = document.getElementById(id); if (el) el.textContent = pad(v);
    });
    // Mini-countdowns on each date card
    miniCards.forEach(([t, ids]) => {
      const df = t - now;
      const vals = df > 0
        ? [Math.floor(df/86400000), Math.floor((df%86400000)/3600000), Math.floor((df%3600000)/60000)]
        : [0, 0, 0];
      ids.forEach((id, i) => { const el = document.getElementById(id); if (el) el.textContent = pad(vals[i]); });
    });
  }
  tick();
  setInterval(tick, 1000);
}

